function UserPage({ userId }: { userId: string }) {
  const { draft, isLoading, resource } = useResource({
    key: ['user', userId],
    persist: { draft: true },
    source: {
      fetch: () => api.getUser(userId),
      save: (d) => api.updateUser(userId, d),
    },
  });

  // Navigating /users/1 → /users/2 recreates the resource automatically
  return isLoading ? null : <ProfileFields resource={resource} name={draft?.name} />;
}

const { resource, save, isValid, isSaving } = useResource({
  key: ['article', 'new'],
  initialData: { title: '', body: '' },
  validate: {
    on: 'submit',
    fields: { title: (v) => (!v ? 'Required' : null) },
  },
  source: {
    save: async (draft) => {
      const created = await api.articles.create(draft);
      navigate(`/articles/${created.id}`);
      return created;
    },
  },
});

function Editor({ id }: { id: string }) {
  const {
    isLoading,
    isFetching,
    isSaving,
    isChanged,
    isValid,
    error,
    mutation,
    save,
    resetDraft,
    refetch,
    resource,
  } = useResource({
    key: id,
    source: {
      fetch: () => api.get(id),
      save: (d) => api.put(id, d),
    },
  });

  if (isLoading) return <Skeleton />;
  if (error) {
    return (
      <div role="alert">
        {String(error)}
        <button type="button" onClick={() => refetch()}>Retry</button>
      </div>
    );
  }

  return (
    <>
      {isFetching && <span>Refreshing…</span>}
      <Fields resource={resource} />
      {mutation.error && <p role="alert">{String(mutation.error)}</p>}
      <button disabled={!isChanged || !isValid || isSaving} onClick={() => save()}>
        {isSaving ? 'Saving…' : 'Save'}
      </button>
      <button type="button" disabled={!isChanged} onClick={resetDraft}>Discard</button>
    </>
  );
}
